    "事象・噂の名称": "アングロフォン危機における分断語彙",
    "実践内容・信じられている内容": "英語圏（北西・南西州）と仏語圏の対立において、互いを貶めるための侮蔑語や特定の政治的レッテルを貼り合う実践。",
    "社会的機能": "相手集団の非人間化、自集団の正当化、政治的対立の明確化",
    "心理的効果": "憎悪の増幅、相互不信、スケープゴート化による心理的防衛",
    "[事実確認]学術的背景・反証": "カメルーンにおける英語圏マイノリティの周縁化と2016年以降の紛争（アングロフォン・クライシス）を背景に、社会言語学や紛争研究で対立を煽るヘイトスピーチとして指摘されている。",
    "事例1：状況": "仏語圏の人間が英語圏の人間を侮蔑する時",
