    "事例1：分析": "Anglophone（英語話者）とFool（馬鹿）を組み合わせた混成語で、英語圏の人間を見下す態度が表れている。",
    "事例2：状況": "英語圏の人間が仏語圏の人間を侮蔑する時",
    "事例2：表現": "「Frog（カエル）」",
