    "事例3：状況": "英語圏の自治・独立運動家を非難する時",
    "事例3：表現": "「Biafrais（ビアフラ人）」",
    "事例3：分析": "隣国ナイジェリアで凄惨な内戦を引き起こしたビアフラ分離独立運動になぞらえ、彼らを「危険な国家の敵」としてレッテル貼りする。"
