    "実践内容・信じられている内容": "目上の人や見知らぬ人に対して親称（Tú）を避け、敬称を用いる言語実践。",
    "社会的機能": "社会的階層と長幼の序の維持。",
    "心理的効果": "敬意の伝達による安心感と、無礼による社会的制裁（村八分）の回避。",
    "[事実確認]学術的背景・反証": "ドミニカ社会はスペイン植民地時代の家父長制とカトリックの階層秩序の色濃い影響を残しており、言語的ポライトネスが社会的地位の承認として機能する。",
