    "事例2：状況": "フォーマルな場での見知らぬ人への声かけ",
    "事例2：表現": "「¿Usted me puede ayudar?（手伝っていただけますか？）」",
    "事例2：分析": "TúではなくUstedを用いることで、社会的距離を保ちつつ敬意を示している。",
    "事例3：状況": "権威者（警察や上司）への応答",
