    "社会的機能": "多様な言語を母語とする民族間での意思疎通を容易にし、視覚的・直感的なイメージを共有して連帯感を生む。",
    "心理的効果": "ユーモラスで素朴な表現による「アハ体験」と、ピジン語特有の親しみやすさ。",
    "[事実確認]学術的背景・反証": "[事実確認]ビスラマ語などのメラネシア・ピジンは基層言語（オーストロネシア語族）の文法や認知構造を反映しており、少ない英単語を組み合わせて豊かな意味を構築する造語法を持つ。",
