    "事例2：分析": "機械を台所用品と宗教用語でしか理解できないと見なす、見下したユーモア。",
    "事例3：状況": "ブラジャーについて語る時",
    "事例3：表現": "baskit blong titi（おっぱいのバスケット）",
    "事例3：分析": "土着の言葉を性的に滑稽化し、笑いの種として消費するための偽語源。"
