    "実践内容・信じられている内容": "親族やコミュニティのメンバーに対し、「Kerekere」という言葉を用いて物や援助を頼むと、断ることが許されないという相互扶助の言語実践。",
    "社会的機能": "富の独占を防ぎ、コミュニティ内での資源の再分配と社会の連帯（Vaka-Viti＝フィジーのやり方）を維持する。",
    "心理的効果": "共同体の一員であるという安心感と同時に、個人の所有物を常に他者に差し出さねばならないという心理的圧力（同調圧力）。",
    "[事実確認]学術的背景・反証": "[事実確認]Kerekere はフィジー社会の中核をなす互酬性のシステムであり、単なる「お願い」を超えた社会制度として文化人類学的に広く研究されている。",
