    "実践内容・信じられている内容": "マタイ（首長）、牧師、来客に対して、日常語とは全く異なる特別な敬意語彙体系を用いてコミュニケーションを行う実践。",
    "社会的機能": "ファア・サモア（サモアの伝統的流儀）の根幹である階層秩序を可視化し、社会の調和と「Va（人間関係の空間・距離）」を維持する。",
    "心理的効果": "目上の者に対する絶対的な敬意の念と、正しい敬語を駆使できることによる「教養あるサモア人」としての誇り・自己肯定感。",
    "[事実確認]学術的背景・反証": "[事実確認]サモアの社会構造（マタイ制度）と密接に結びついた敬語体系。オラトリー（Tulafale＝雄弁家）文化において、適切な敬語の使用は社会的権力と直結する社会言語学的事実。",
    "事例1：状況": "首長や目上の人の食事に言及する時",
    "事例1：表現": "日常語の「'Ai（食べる）」を避け、「Taumafa」や「Tausami」を使用する。",
    "事例1：分析": "行為を上昇させる特別な語彙を用いることで、マタイの身体的欲求を儀式化・神聖化し、平民と区別する。",
    "事例2：状況": "首長が話す、または言葉を発する時",
    "事例2：表現": "日常語の「Tautala（話す）」ではなく、「Saunoa」や「Tala fofoga」を用いる。",
    "事例2：分析": "首長の発言を単なる音声コミュニケーションではなく、権威ある布告・叡智の開示として位置づける。",
    "事例3：状況": "首長の顔や目について言及する時",
    "事例3：表現": "日常語の「Mata（顔・目）」ではなく、「Fofoga」を用いる。",
    "事例3：分析": "首長の身体部位（特に頭部）は伝統的に神聖（Tapu）とされており、特別な語彙でその不可侵性を表現する。"
