    "事象・噂の名称": "接頭辞「fia-（〜ぶる）」を用いたレッテル貼りと社会的制裁",
    "実践内容・信じられている内容": "共同体の調和や平等から逸脱して自己主張する者に対し、「fia-〇〇（〜のふりをする、〜ぶる）」という言葉を投げかけ、非難する実践。",
    "社会的機能": "エゴや過度な個人主義を抑制し、サモアの伝統的価値観（共同体への奉仕）を維持するための同調圧力・キャンセルとして機能する。",
    "心理的効果": "共同体から疎外されることへの恐れによる謙遜の強制と、攻撃する側の「伝統の守護者」としての優越感。",
    "[事実確認]学術的背景・反証": "[事実確認]サモア社会は集団主義的であり、「Fa'a Samoa」に反する態度は制裁の対象となる。社会言語学的に「fia-」は集団の規範から外れた者を矯正する強力なアイデンティティ・マーカーである。",
    "事例1：状況": "海外帰りの若者が英語を多用し、サモアの習慣を軽視した時",
