    "事例1：分析": "西洋化（Palagi）を気取ることを「文化的忘恩」として非難し、サモアのアイデンティティへの服従を迫る。",
    "事例2：状況": "正当な権限のない者が他人に命令したり、仕切りたがったりする時",
    "事例2：表現": "Fia pule.（ボスぶるな／権力者ぶるな）",
    "事例2：分析": "マタイ（首長）などの正当な権力を持たない者の越権行為を即座に叩き、村や家族内の階層秩序を守る。",
    "事例3：状況": "会議や議論の場で、自分の知識をひけらかし他者を見下した時",
    "事例3：表現": "Fia poto.（賢ぶるな）",
    "事例3：分析": "知識を個人的な優位性の誇示に使うことを「傲慢」と見なし、共同体への貢献という本来の知恵のあり方から逸脱しているとキャンセルする。"
